def is_nested(string):
    stack = []
    has_nested = False

    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
                if stack:  # If there's still an open bracket, we have a nested structure
                    has_nested = True

    return has_nested

